using System;
using System.IO;
using System.Linq;
using System.Threading;
using NAudio.Wave;
using NAudio.CoreAudioApi;
namespace LoopPedal {
static class AudioChecks {
 public static void DualHardware(){try{string driver=AsioOut.GetDriverNames().First(x=>x.IndexOf("ZOOM L6max",StringComparison.OrdinalIgnoreCase)>=0);using(var a=new Engine())using(var b=new Engine()){a.Partner=b;b.ClockLeader=a;a.Master=b.Master=0;a.Sync=b.Sync=true;a.BPM=b.BPM=240;a.Bars=1;b.Bars=3;a.Open(driver,null,new[]{new SourceChoice{Name="In 1",Left=0,Right=0}},new OutputChoice{Offset=0});a.Begin(false);b.Begin(false);DateTime end=DateTime.UtcNow.AddSeconds(6);while(DateTime.UtcNow<end&&(a.Recording||b.Recording)){if(a.RecordingComplete)a.Finish();if(b.RecordingComplete)b.Finish();Thread.Sleep(10);}if(a.Error!=null)throw new Exception(a.Error);if(a.Recording||b.Recording||a.Layers.Count!=1||b.Layers.Count!=1||a.Layers[0].Audio.Length!=96000||b.Layers[0].Audio.Length!=288000)throw new Exception("Dual hardware capture lengths failed");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"dual-hardware-tests.txt"),"PASS: real Zoom ASIO stream shared by two simultaneous loopers; independent exact 1-second/3-second captures; silent output; no backend error.");}}catch(Exception e){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"dual-hardware-tests.txt"),"FAIL: "+e);Environment.ExitCode=1;}}
 public static void Dual(){try{
  if(Engine.MeasureFrames(120,4,4,1)!=96000||Engine.MeasureFrames(120,6,8,1)!=72000||Engine.MeasureFrames(120,3,4,2)!=144000)throw new Exception("Measure duration calculation failed");
  using(var a=new Engine())using(var b=new Engine()){a.Partner=b;b.ClockLeader=a;a.Sync=b.Sync=true;a.BPM=b.BPM=120;a.Bars=1;b.Bars=3;a.CountInBars=1;var source=new SourceChoice{Name="Test",Left=0,Right=1};a.Inputs.Add(new Input(source));b.Inputs.Add(new Input(source));a.Begin(false);b.Begin(false);if(a.RecordStartAudio!=96000||b.RecordStartAudio!=0)throw new Exception("Count-in schedule failed");var block=Enumerable.Repeat(.1f,512).ToArray();var output=new byte[512*4];var provider=new LoopProvider(a);double click=0;for(int chunk=0;chunk<1125;chunk++){long ta=a.AudioFrame,tb=b.AudioFrame;a.Inputs[0].Feed(block,block.Length,2,ta);b.Inputs[0].Feed(block,block.Length,2,tb);provider.Read(output,0,output.Length);if(chunk<375){if(a.Inputs[0].Take.Count!=0)throw new Exception("Count-in leaked into recording");var floats=new float[512];System.Buffer.BlockCopy(output,0,floats,0,output.Length);foreach(var v in floats)click=Math.Max(click,Math.Abs(v));}if(a.RecordingComplete)a.Finish();if(b.RecordingComplete)b.Finish();}
   if(click<.01||a.Layers.Count!=1||b.Layers.Count!=1||a.LoopFrames!=96000||b.LoopFrames!=288000)throw new Exception("Independent timed captures/count-in failed");if(a.Layers[0].Audio.Any(x=>Math.Abs(x-.1f)>.00001)||b.Layers[0].Audio.Any(x=>Math.Abs(x-.1f)>.00001))throw new Exception("Capture changed level");
   a.Frame=a.Layers[0].Offset+96000+1000;b.Frame=b.Layers[0].Offset+96000+1000;if(Math.Abs(Engine.Phase(a.Frame-a.Layers[0].Offset,96000)-Engine.Phase(b.Frame-b.Layers[0].Offset,288000))<.2)throw new Exception("Short/long phases not independent");provider.Read(output,0,output.Length);var mix=new float[512];System.Buffer.BlockCopy(output,0,mix,0,output.Length);if(mix.Max()>.20001||mix.Min()<0)throw new Exception("Dual mix gained unexpectedly");long held=b.Frame;b.Playing=false;provider.Read(output,0,output.Length);if(b.Frame!=held||a.Frame<=a.Layers[0].Offset+97000)throw new Exception("Independent transport failed");
   for(int i=-500;i<500;i++)if(Math.Abs(Engine.Edge(a.Layers[0].Audio,i,0)-.1)>.000001)throw new Exception("Seam fades through silence");
  }
  File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"dual-tests.txt"),"PASS: BPM/time signatures/measures; one-measure count-in excluded from capture; two simultaneous independent timed loopers; exact 1:3 lengths; unity capture; independent transport/phases; constant-gain seam crossfade.");
 }catch(Exception e){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"dual-tests.txt"),"FAIL: "+e);Environment.ExitCode=1;}}
 public static void Recording(){try{using(var e=new Engine()){
  var route=new Input(new SourceChoice{Name="Stereo",Left=0,Right=1});e.Inputs.Add(route);var input=new float[96000];for(int i=0;i<48000;i++){input[i*2]=(float)(.25*Math.Sin(2*Math.PI*440*i/48000));input[i*2+1]=(float)(.19*Math.Sin(2*Math.PI*660*i/48000));}
  e.Frame=1379;e.Begin(false);route.Feed(input,input.Length,2);e.Finish();var first=e.Layers[0];if(first.Offset!=1379||!first.Original.SequenceEqual(input))throw new Exception("Recorded source was rotated, summed, or gained");
  e.Frame=first.Offset+4800;var output=new float[40000];e.Mix(output,20000);double maxError=0;for(int i=8192;i<output.Length;i++)maxError=Math.Max(maxError,Math.Abs(output[i]-input[9600+i]));if(maxError>.0000001)throw new Exception("Playback gain differs from recorded input: "+maxError);
  var discontinuous=Enumerable.Range(0,48000).SelectMany(i=>new[]{(float)(-.7+1.4*i/47999), (float)(.7-1.4*i/47999)}).ToArray();e.Frame=120123;e.Begin(false);route.Feed(discontinuous,discontinuous.Length,2);e.Finish();var seam=e.Layers[1];first.Mute=true;e.Frame=seam.Offset+47000;output=new float[8000];e.Mix(output,4000);double jump=0;for(int i=400;i<4000;i++)jump=Math.Max(jump,Math.Abs(output[i*2]-output[(i-1)*2]));if(jump>.015)throw new Exception("Actual record join clicks at nonzero offset: "+jump);
  e.Frame=345678;e.Begin(false);var longer=Enumerable.Repeat(.2f,192000).ToArray();route.Feed(longer,longer.Length,2);e.Finish();if(e.Layers[2].Audio.Length!=longer.Length||e.Layers[2].Audio.Max()>.200001f)throw new Exception("Long take folded and amplified itself");
  e.Begin(true);route.Feed(longer,longer.Length,2);e.Finish();if(e.Layers[3].Audio.Length!=e.LoopFrames*2||e.Layers[3].Audio.Max()>.200001f)throw new Exception("Overdub wrapped/summed instead of stopping at one cycle");
  File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"recording-tests.txt"),"PASS: exact captured samples; unity input/playback level; actual join fades at nonzero start offset; long take does not fold/amplify; overdub does not sum extra passes. Maximum boundary delta: "+jump);
 }}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"recording-tests.txt"),"FAIL: "+ex);Environment.ExitCode=1;}}
 public static void Quality(){string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"quality-roundtrip.wav");try{
  var samples=new[]{1.25f,-1.25f,1.1234567e-10f,-.9876543f,.00000011920928955f,-.00000011920928955f};if(!object.ReferenceEquals(DSP.Render(samples,1,0,false),samples))throw new Exception("Unity render changed source");var reverse=DSP.Render(samples,1,0,true);if(reverse[0]!=samples[4]||reverse[1]!=samples[5])throw new Exception("Reverse damaged channel alignment");
  DSP.Wav(path,samples);using(var reader=new WaveFileReader(path)){if(reader.WaveFormat.BitsPerSample!=32||reader.WaveFormat.Encoding!=WaveFormatEncoding.IeeeFloat)throw new Exception("Export is not float32");var raw=new byte[samples.Length*4];reader.Read(raw,0,raw.Length);int count;var decoded=new NativeCapture(reader.WaveFormat).Convert(raw,raw.Length,out count);if(count!=samples.Length||!samples.SequenceEqual(decoded.Take(count)))throw new Exception("Float WAV did not round-trip exactly");}
  var pcm=new NativeCapture(new WaveFormat(48000,24,2));int converted;var decoded24=pcm.Convert(new byte[]{1,0,0,255,255,255},6,out converted);if(decoded24[0]!=1/8388608f||decoded24[1]!=-1/8388608f)throw new Exception("24-bit source precision lost");
  var resample=new NativeCapture(WaveFormat.CreateIeeeFloatWaveFormat(96000,2));var signal=new float[96000*2];for(int i=0;i<96000;i++)signal[i*2]=signal[i*2+1]=(float)(.5*Math.Sin(2*Math.PI*30000*i/96000));var bytes=new byte[signal.Length*4];System.Buffer.BlockCopy(signal,0,bytes,0,bytes.Length);var down=resample.Convert(bytes,bytes.Length,out converted);double energy=0;int measured=0;for(int i=4000;i<converted-4000;i++){energy+=down[i]*down[i];measured++;}double rms=Math.Sqrt(energy/measured);if(rms>.001)throw new Exception("Resampler alias rejection failed: "+rms);
  using(var e=new Engine()){var wave=Enumerable.Repeat(.25f,96000).ToArray();e.Master=1;e.Frame=1000;e.Layers.Add(new Layer{Original=wave,Audio=wave,Gain=1});var output=new float[20000];e.Mix(output,10000);if(Math.Abs(output[19998]-.25f)>.00001)throw new Exception("Default signal path is not transparent");}
  File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"quality-tests.txt"),"PASS: bit-exact unity bypass; exact stereo reverse; 32-bit float WAV round-trip including headroom and quiet detail; 24-bit PCM precision; sinc resampling alias rejection; transparent open filter and output.");
 }catch(Exception e){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"quality-tests.txt"),"FAIL: "+e);Environment.ExitCode=1;}finally{if(File.Exists(path))File.Delete(path);}}
 public static void Lengths(){try{
  var source=new float[96000];for(int i=0;i<48000;i++){source[i*2]=i/48000f;source[i*2+1]=-source[i*2];}
  var crop=DSP.Trim(source,.25,.5);if(crop.Length!=48000||crop[0]!=source[24000]||crop[1]!=source[24001]||crop[crop.Length-2]!=source[71998])throw new Exception("Trim bounds or stereo alignment failed");
  var rendered=DSP.Render(crop,1.5,0,false);if(rendered.Length!=72000||rendered.Any(x=>float.IsNaN(x)||float.IsInfinity(x)))throw new Exception("Trim/stretch duration failed");
  if(!object.ReferenceEquals(DSP.Trim(source,0,1),source))throw new Exception("Full take was not restored");if(DSP.Trim(source,.9,.5).Length!=9600)throw new Exception("End clamp failed");if(DSP.Trim(source,1,0).Length!=2)throw new Exception("Minimum length failed");
  using(var e=new Engine()){var first=new Layer{Original=source,Audio=source,Gain=1};var second=new Layer{Original=source,Audio=source,Gain=0};e.Layers.Add(first);e.Layers.Add(second);var pcm=new float[4096];e.Frame=15000;e.Mix(pcm,2048);first.PreviousAudio=first.Audio;first.Audio=crop;first.Transition=960;e.Mix(pcm,2048);if(first.PreviousAudio!=null||first.Transition!=0)throw new Exception("Trim crossfade did not finish");if(second.Audio.Length!=source.Length||!object.ReferenceEquals(first.Original,source))throw new Exception("Trimming changed another layer or destroyed the original");}
  File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"length-tests.txt"),"PASS: stereo trim bounds; duration after stretch; full restore; end/minimum clamps; live crossfade; independent layers; original preserved.");
 }catch(Exception e){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"length-tests.txt"),"FAIL: "+e);Environment.ExitCode=1;}}
 public static void Run(){using(var log=new StreamWriter(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"audio-checks.txt"))){try{
 // Route channel 13 alone, then a stereo pair, from a synthetic 14-channel buffer.
 var mono=new Input(new SourceChoice{Name="13",Left=12,Right=12}){Take=new RecordedAudio(100),Limit=100};var stereo=new Input(new SourceChoice{Name="5",Left=4,Right=5}){Take=new RecordedAudio(100),Limit=100};var data=new float[28];for(int i=0;i<data.Length;i++)data[i]=i/100f;mono.Feed(data,28,14);stereo.Feed(data,28,14);if(mono.Take[0]!=.12f||mono.Take[1]!=.12f||stereo.Take[0]!=.04f||stereo.Take[1]!=.05f)throw new Exception("Channel routing failed");log.WriteLine("PASS · independent mono/stereo routing from 14-channel stream");
 using(var e=new Engine()){var wave=new float[96000];for(int i=0;i<wave.Length;i++)wave[i]=.5f;var layer=new Layer{Name="Seam test",Original=wave,Audio=wave,Gain=1};e.Layers.Add(layer);e.Frame=47900;float[] pcm=new float[1600];e.Mix(pcm,800);float max=0;for(int i=1;i<800;i++)max=Math.Max(max,Math.Abs(pcm[i*2]-pcm[(i-1)*2]));if(max>.0275)throw new Exception("Boundary discontinuity: "+max);layer.Mute=true;e.Mix(pcm,800);if(Math.Abs(pcm[1598])>.045)throw new Exception("Mute smoothing failed");log.WriteLine("PASS · loop seam and mute ramp; maximum seam delta "+max);}
 // Open real Zoom hardware with all channels, record silence/output disabled, and verify all routes receive frames.
 string zoom=AsioOut.GetDriverNames().FirstOrDefault(x=>x.IndexOf("ZOOM L6max",StringComparison.OrdinalIgnoreCase)>=0);if(zoom!=null){using(var d=new AsioOut(zoom)){int count=d.DriverInputChannelCount;log.WriteLine("ZOOM · "+count+" inputs / "+d.DriverOutputChannelCount+" outputs");var choices=Enumerable.Range(0,count).Select(i=>new SourceChoice{Name=d.AsioInputChannelName(i),Left=i,Right=i}).ToArray();using(var e=new Engine()){e.Open(zoom,d,choices,new OutputChoice{Offset=0});e.Begin(false);Thread.Sleep(350);e.Playing=false;e.Finish();if(e.Error!=null)throw new Exception(e.Error);if(e.Layers.Count!=count)throw new Exception("Expected "+count+" captured layers; got "+e.Layers.Count);log.WriteLine("PASS · Zoom capture all "+count+" channels, "+e.LoopFrames+" frames");e.StopAudio();if(e.Layers.Count!=count)throw new Exception("Switch lost layers");log.WriteLine("PASS · stopping/switching audio preserves layers");}}}
 // Probe Model:Cycles in Windows shared mode at the engine rate. Output is always silent in this test.
 using(var devices=new MMDeviceEnumerator()){var inputs=devices.EnumerateAudioEndPoints(DataFlow.Capture,DeviceState.Active);var outputs=devices.EnumerateAudioEndPoints(DataFlow.Render,DeviceState.Active);var input=inputs.FirstOrDefault(x=>x.FriendlyName.IndexOf("Model:Cycles",StringComparison.OrdinalIgnoreCase)>=0);var output=outputs.FirstOrDefault(x=>x.FriendlyName.IndexOf("Model:Cycles",StringComparison.OrdinalIgnoreCase)>=0);if(input!=null&&output!=null){log.WriteLine("MODEL:CYCLES · "+input.AudioClient.MixFormat);using(var e=new Engine()){e.Open(null,null,new[]{new SourceChoice{Name="Cycles",Endpoint=input.ID,Left=0,Right=1}},new OutputChoice{Endpoint=output.ID});e.Begin(false);Thread.Sleep(350);e.Playing=false;e.Finish();if(e.Error!=null)throw new Exception(e.Error);if(e.Layers.Count!=1)throw new Exception("Cycles received no samples");log.WriteLine("PASS · Model:Cycles negotiated-format input/output, "+e.LoopFrames+" captured frames");}}else log.WriteLine("SKIP · Model:Cycles not connected");foreach(var device in inputs)device.Dispose();foreach(var device in outputs)device.Dispose();}
 log.WriteLine("PASS · audio checks complete");}catch(Exception e){log.WriteLine("FAIL · "+e);Environment.ExitCode=1;}}}
}
}




